DROP TABLE IF EXISTS `Student_app_student_marks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Student_app_student_marks` (
  `id` varchar(25) NOT NULL,
  `stu_enroll` varchar(12) NOT NULL,
  `stu_sem` int NOT NULL,
  `stu_term` varchar(5) NOT NULL,
  `stu_name` varchar(50) NOT NULL,
  `sub_name` varchar(50) NOT NULL,
  `stu_branch_code` varchar(2) NOT NULL,
  `stu_sub_code` int NOT NULL,
  `session` varchar(50) NOT NULL,
  `stu_theory_ESE` int NOT NULL,
  `stu_theory_PA` int NOT NULL,
  `stu_practical_ESE` int NOT NULL,
  `stu_practical_PA` int NOT NULL,
  `Assigned_Sub_Faculty_id` int DEFAULT NULL,
  `student_id` varchar(12) NOT NULL,
  `subject_id` varchar(10) NOT NULL,
  `is_passed` tinyint(1) NOT NULL,
  `year` varchar(4) NOT NULL,
  `marks_entered` tinyint(1) NOT NULL,
  `exam_type` varchar(14) NOT NULL,
  `is_remedial` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `Student_app_student__Assigned_Sub_Faculty_764ae25c_fk_faculty_f` (`Assigned_Sub_Faculty_id`),
  KEY `Student_app_student__student_id_729410e6_fk_Student_a` (`student_id`),
  KEY `Student_app_student__subject_id_a564e0b1_fk_main_sub_` (`subject_id`),
  CONSTRAINT `Student_app_student__Assigned_Sub_Faculty_764ae25c_fk_faculty_f` FOREIGN KEY (`Assigned_Sub_Faculty_id`) REFERENCES `faculty_faculty_records` (`fac_id`),
  CONSTRAINT `Student_app_student__student_id_729410e6_fk_Student_a` FOREIGN KEY (`student_id`) REFERENCES `Student_app_student` (`stu_enroll`),
  CONSTRAINT `Student_app_student__subject_id_a564e0b1_fk_main_sub_` FOREIGN KEY (`subject_id`) REFERENCES `main_sub_syllabus` (`sub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

